85	    // By default, we compute all groups for SQL compliant results. However, we allow overriding this behavior via
86	    // query option for improved performance.
87	    _filteredAggregationsSkipEmptyGroups = QueryOptionsUtils.isFilteredAggregationsSkipEmptyGroups(opChainMetadata);
88	
89	    int numFunctions = aggFunctions.length;
90	    if (!aggType.isInputIntermediateFormat()) {
91	      _aggregateResultHolders = new GroupByResultHolder[numFunctions];
92	      for (int i = 0; i < numFunctions; i++) {
93	        _aggregateResultHolders[i] =
