40	    /**
41	     * Sort comparator for use with priority queues.
42	     *
43	     * @param dataSchema data schema to use
44	     * @param collations collations to sort on
45	     * @param reverse 'true' if the opposite sort direction should be used as what is specified
46	     */
47	    public SortComparator(DataSchema dataSchema, List<RelFieldCollation> collations, boolean reverse) {
48	      DataSchema.ColumnDataType[] columnDataTypes = dataSchema.getColumnDataTypes();
49	      _numFields = collations.size();
50	      _valueIndices = new int[_numFields];
51	      _multipliers = new int[_numFields];
52	      _nullsMultipliers = new int[_numFields];
53	      _useDoubleComparison = new boolean[_numFields];
54	      for (int i = 0; i < _numFields; i++) {
55	        RelFieldCollation collation = collations.get(i);
56	        _valueIndices[i] = collation.getFieldIndex();
57	        int multiplier = collation.direction == Direction.ASCENDING ? 1 : -1;
58	        _multipliers[i] = reverse ? -multiplier : multiplier;
59	        boolean nullsLast =
60	            collation.nullDirection == NullDirection.LAST || (collation.nullDirection == NullDirection.UNSPECIFIED
61	                && collation.direction == Direction.ASCENDING);
62	        int nullsMultiplier = nullsLast ? 1 : -1;
63	        _nullsMultipliers[i] = reverse ? -nullsMultiplier : nullsMultiplier;
64	        _useDoubleComparison[i] = columnDataTypes[_valueIndices[i]].isNumber();
65	      }
66	    }
