69	    public int compare(Object[] o1, Object[] o2) {
70	      for (int i = 0; i < _numFields; i++) {
71	        int index = _valueIndices[i];
72	        Object v1 = o1[index];
73	        Object v2 = o2[index];
74	        if (v1 == null) {
75	          if (v2 == null) {
76	            continue;
77	          }
78	          return _nullsMultipliers[i];
79	        }
80	        if (v2 == null) {
81	          return -_nullsMultipliers[i];
82	        }
83	        int result;
84	        if (_useDoubleComparison[i]) {
85	          result = Double.compare(((Number) v1).doubleValue(), ((Number) v2).doubleValue());
86	        } else {
87	          //noinspection rawtypes,unchecked
88	          result = ((Comparable) v1).compareTo(v2);
89	        }
90	        if (result != 0) {
91	          return result * _multipliers[i];
92	        }
93	      }
